    this.showToast("🍏 iPhone MODE: uključen ✅  Sada izaberi simptom i pritisni ▶ POKRENI.", { timeoutMs: 9000 });
    try { const b = document.getElementById("unlock-audio-btn"); if (b) b.style.display = "none"; } catch(_) {}
