    const versionBlock = `
      <section class="lab-report-section">
        <h3>Versioning + QA gate</h3>
        <div class="lab-kpi">
          <div class="lab-kpi-card"><b>QA status</b>${this.escapeHtml(qa.status || 'unknown')}</div>
          <div class="lab-kpi-card"><b>prompt_version</b>${this.escapeHtml(meta.prompt_version || LAB_PROMPT_VERSION)}</div>
          <div class="lab-kpi-card"><b>schema_version</b>${this.escapeHtml(meta.schema_version || LAB_SCHEMA_VERSION)}</div>
          <div class="lab-kpi-card"><b>render_version</b>${this.escapeHtml(meta.render_version || LAB_RENDER_VERSION)}</div>
        </div>
        ${arrify(qa.issues).length ? `<div style="margin-top:12px;">${this._labListHtml(qa.issues, 'QA bez napomena.')}</div>` : '<div class="lab-inline-note" style="margin-top:12px;">QA gate nije prijavio strukturne probleme.</div>'}
      </section>`;
    return base.replace(/<\/div>\s*$/, `${versionBlock}</div>`);
