  const origLabHandleInputFiles27 = App.prototype.labHandleInputFiles;
  App.prototype.labHandleInputFiles = async function(input) {
    const file = input?.files?.[0];
    const meta = document.getElementById('lab-file-meta');
    if (!file || !meta) return;
    const neutralName = this._neutralLabAttachmentName(file.name, file.type || '');
    const info = {
      display_name: neutralName,
      neutral_name: neutralName,
      ext: (String(file.name || '').split('.').pop() || '').toLowerCase(),
      size: file.size,
      type: file.type || '',
      lastModified: file.lastModified || 0,
      gdpr_sanitized: true,
      source_type: /pdf/i.test(file.type || '') || /\.pdf$/i.test(file.name || '') ? 'pdf_reference' : 'local_upload'
    };
    meta.dataset.payload = JSON.stringify(info);
    const ext = info.ext;
    if (['txt','md','json','html','htm'].includes(ext) || /^text\//.test(file.type || '')) {
      const raw = await file.text();
      let text = raw;
      if (ext === 'html' || ext === 'htm' || /html/.test(file.type || '')) {
        try {
          const doc = new DOMParser().parseFromString(raw, 'text/html');
          text = String(doc.body?.innerText || raw).trim();
        } catch(_) {}
      }
      const ta = document.getElementById('lab_raw_text');
      if (ta) ta.value = this.gdprSanitizeLabText(text);
      meta.innerHTML = `Učitano: <b>${this.escapeHtml(neutralName)}</b> • ${(file.size/1024).toFixed(1)} KB • GDPR sanitize ON`;
      this.showToast('LAB prilog učitan i neutralisan za prikaz ✅');
      return;
    }
    if (ext === 'pdf' || /pdf/.test(file.type || '')) {
      const ta = document.getElementById('lab_raw_text');
      if (ta && !ta.value.trim()) ta.value = '[PDF prilog] [GDPR-NEUTRALNO]\n\nNapomena: offline demo za sada ne parsira PDF automatski. Nalepi tekst nalaza ili koristi ovaj prilog kao referencu.';
      meta.innerHTML = `PDF priložen: <b>${this.escapeHtml(neutralName)}</b> • ${(file.size/1024).toFixed(1)} KB • parser dolazi u sledećem talasu • GDPR sanitize ON`;
      this.showToast('PDF je zabeležen sa neutralnim imenom.');
      return;
    }
    meta.innerHTML = `Prilog: <b>${this.escapeHtml(neutralName)}</b> • format nije direktno podržan za tekstualni import.`;
  };

  const origRenderLabReportFromInput27 = App.prototype.renderLabReportFromInput;
  App.prototype.renderLabReportFromInput = function() {
    const ta = document.getElementById('lab_ai_json');
    const raw = String(ta?.value || '').trim();
    if (!raw) return alert('Nalepi AI JSON rezultat.');
    const parsed = this._parseAiJsonLoose ? this._parseAiJsonLoose(raw) : null;
    if (!parsed || !parsed.obj) return alert('LAB JSON nije validan.');
    if (ta) ta.value = JSON.stringify(parsed.obj, null, 2);
    const report = this._normalizeLabReportObject(parsed.obj, this.collectLabInput());
    this._labCurrentReport = report;
    try { localStorage.setItem('SINET_LAB_LAST_REPORT_V1', JSON.stringify(report)); } catch(_) {}
    this.renderLabReportToDom(report);
    this.showToast(`SINET Lab report renderovan ✅ (QA: ${report.qa?.status || 'n/a'})`);
    this.log('USER', 'Lab Report Render v16.0.0.27', report.metadata?.report_id || report.patient?.name || 'LAB');
    try { this.renderHealthRecord(); } catch(_) {}
  };

  App.prototype.copyCurrentLabJson = async function() {
    const report = this._labCurrentReport || safeParse(localStorage.getItem('SINET_LAB_LAST_REPORT_V1') || 'null', null);
    if (!report) return alert('Nema LAB JSON sadržaja za kopiranje.');
    const text = JSON.stringify(report, null, 2);
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) await navigator.clipboard.writeText(text);
      else throw new Error('clipboard-api-unavailable');
      this.showToast('KOPIRAJ JSON REZULTAT ✅');
    } catch(_) {
      this.openTextModal('📋 KOPIRAJ JSON REZULTAT', text);
    }
  };

  const origDownloadCurrentLabHtml27 = App.prototype.downloadCurrentLabHtml;
  App.prototype.downloadCurrentLabHtml = function() {
    const report = this._labCurrentReport || safeParse(localStorage.getItem('SINET_LAB_LAST_REPORT_V1') || 'null', null);
    if (!report) return alert('Nema laboratorijskog izveštaja za preuzimanje.');
    const html = this._labReportDocument(report);
    const filename = `SINET_LAB_REPORT_${slugify(report.metadata?.report_id || report.title)}_${todayIso()}.html`;
    this._downloadText(html, filename);
  };

  const origExportCurrentLabJson27 = App.prototype.exportCurrentLabJson;
  App.prototype.exportCurrentLabJson = function() {
    const report = this._labCurrentReport || safeParse(localStorage.getItem('SINET_LAB_LAST_REPORT_V1') || 'null', null);
    if (!report) return alert('Nema LAB JSON sadržaja za izvoz.');
    this._downloadJson(report, `SINET_LAB_REPORT_${slugify(report.metadata?.report_id || report.title)}_${todayIso()}.json`);
  };

  App.prototype._syncHealthRecordFromLabSnapshot = function(snap) {
    if (!snap) return;
    const hr = this._getHealthRecord();
    hr.profile.display_name = snap.patient_name || hr.profile.display_name || 'Korisnik';
    hr.current_snapshot = {
      summary: arrify(snap.quick_summary).slice(0, 3),
      priorities: arrify(snap.key_findings).slice(0, 5),
      next_steps: arrify(snap.next_steps).slice(0, 5),
      red_flags: arrify(snap.red_flags).slice(0, 5),
      last_report_date: snap.report_date || '',
      last_lab_snapshot_id: snap.id || '',
      last_update: new Date().toISOString()
    };
    hr.lab_snapshots = dedupeById([snap, ...arrify(hr.lab_snapshots)]).slice(0, 50);
    hr.audit.last_sync_source = 'LAB Bridge';
    hr.audit.last_lab_snapshot_id = snap.id || '';
    hr.audit.last_render_version = LAB_RENDER_VERSION;
    this._saveHealthRecord(hr);
  };

  const origSaveCurrentLabSnapshot27 = App.prototype.saveCurrentLabSnapshot;
  App.prototype.saveCurrentLabSnapshot = function() {
    const before = this._labSnapshots ? this._labSnapshots() : [];
    origSaveCurrentLabSnapshot27.apply(this, arguments);
    const after = this._labSnapshots ? this._labSnapshots() : [];
    const snap = after[0] || before[0] || null;
    if (snap) this._syncHealthRecordFromLabSnapshot(snap);
    try { this.renderHealthRecord(); } catch(_) {}
  };

