  App.prototype._renderHealthRecordCompareAndAttachments = function(hr) {
    const snaps = arrify(hr.lab_snapshots).slice(0, 50);
    const optHtml = (s) => `<option value="${this.escapeHtml(String(s.id||''))}">${this.escapeHtml((s.report_date||'') + ' — ' + (s.title||s.patient_name||'Lab Snapshot'))}</option>`;
    const selA = document.getElementById('hr-compare-a');
    const selB = document.getElementById('hr-compare-b');
    const selC = document.getElementById('hr-compare-c');
    const fill = (sel) => {
      if (!sel) return;
      const cur = sel.value || '';
      sel.innerHTML = `<option value="">— izaberi —</option>` + snaps.map(optHtml).join('');
      if (cur) sel.value = cur;
    };
    fill(selA); fill(selB); fill(selC);

    const tType = document.getElementById('hr-attach-target-type');
    const tSel = document.getElementById('hr-attach-target-id');
    if (tType && tSel) {
      const cur = tSel.value || '';
      const mode = String(tType.value || 'event');
      const list = mode === 'therapy' ? arrify(hr.therapy_records) : arrify(hr.medical_events);
      tSel.innerHTML = `<option value="">— izaberi —</option>` + list.map(it => {
        const label = [it.date, (mode==='therapy'? (it.name||'Terapija') : (it.title||'Događaj'))].filter(Boolean).join(' • ');
        return `<option value="${this.escapeHtml(String(it.id||''))}">${this.escapeHtml(label)}</option>`;
      }).join('');
      if (cur) tSel.value = cur;
      if (!tSel.value && list[0]?.id) tSel.value = String(list[0].id);
      tType.onchange = () => { try { this._renderHealthRecordCompareAndAttachments(this._getHealthRecord()); } catch(_) {} };
    }

    const host = document.getElementById('hr-attachments-list');
    if (host) {
      const atts = arrify(hr.attachments);
      host.innerHTML = atts.length ? atts.map(a => `
        <div class="hr-list-card">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;">
            <div style="font-weight:900;color:#1f3f5b;">${this.escapeHtml(a.name||'prilog')}</div>
            <div class="hr-sub">${this.escapeHtml([a.kind, (a.size||0)+' B', (a.created_at||'').slice(0,16).replace('T',' ')].filter(Boolean).join(' • '))}</div>
          </div>
          <div style="margin-top:10px;">${this._hrAttachmentChipHtml(a)}</div>
        </div>
      `).join('') : '<div class="lab-empty">Još nema priloga.</div>';
    }
  };

  App.prototype._renderHealthRecordSpecialistViews = function(hr) {
    const host = document.getElementById('hr-specialist-views');
    if (!host) return;
    const sv = hr.specialist_views || {};
    const views = arrify(sv.views);
    if (!views.length) {
      host.innerHTML = '<div class="lab-empty">Nema specialist view-a još. Pokreni Compare (A/B) da se generiše na osnovu izabranog snapshot-a.</div>';
      return;
    }
    host.innerHTML = `
      <div class="lab-inline-note">based_on_snapshot_id: <b>${this.escapeHtml(String(sv.based_on_snapshot_id||''))}</b> • generated_at: ${this.escapeHtml(String(sv.generated_at||''))}</div>
      ${views.map(v => `
        <div class="hr-list-card">
          <div style="font-weight:900;color:#1f3f5b;">${this.escapeHtml(v.title||v.id)}</div>
          ${arrify(v.focus).length ? `<div style="margin-top:10px;">${arrify(v.focus).map(x=>`<span class="hr-tag">${this.escapeHtml(String(x))}</span>`).join('')}</div>` : '<div class="hr-sub">Nema eksplicitnih tagova za ovaj view (ili nije prepoznato u nalazu).</div>'}
          ${arrify(v.red_flags).length ? `<div style="margin-top:10px;"><b>Red flags</b>${arrify(v.red_flags).map(x=>`<div class="hr-mini">• ${this.escapeHtml(String(x))}</div>`).join('')}</div>` : ''}
          ${arrify(v.next_steps).length ? `<div style="margin-top:10px;"><b>Sledeći koraci</b>${arrify(v.next_steps).map(x=>`<div class="hr-mini">• ${this.escapeHtml(String(x))}</div>`).join('')}</div>` : ''}
          ${arrify(v.questions).length ? `<div style="margin-top:10px;"><b>Pitanja za lekara</b>${arrify(v.questions).map(x=>`<div class="hr-mini">• ${this.escapeHtml(String(x))}</div>`).join('')}</div>` : ''}
        </div>
      `).join('')}
    `;
  };

