  App.prototype.downloadCurrentAttachment = function() {
    const id = this._hrCurrentAttachmentId;
    if (!id) return;
    const hr = this._getHealthRecord();
    const att = this._hrGetAttachmentById(hr, id);
    if (!att) return;
    if (!att.inline || !att.data_url) return alert('Nema inline sadržaja za preuzimanje (metadata-only).');
    const a = document.createElement('a');
    a.href = att.data_url;
    a.download = att.name || 'prilog';
    document.body.appendChild(a);
    a.click();
    a.remove();
  };

  App.prototype.deleteCurrentAttachment = function() {
    const id = this._hrCurrentAttachmentId;
    if (!id) return;
    if (!confirm('Obrisati prilog?')) return;
    const hr = this._getHealthRecord();
    hr.attachments = Array.isArray(hr.attachments) ? hr.attachments : [];
    hr.attachments = hr.attachments.filter(a => String(a.id) !== String(id));
    hr.medical_events.forEach(e => { e.attachment_ids = (Array.isArray(e.attachment_ids)? e.attachment_ids: []).filter(x => String(x) !== String(id)); });
    hr.therapy_records.forEach(t => { t.attachment_ids = (Array.isArray(t.attachment_ids)? t.attachment_ids: []).filter(x => String(x) !== String(id)); });
    this._saveHealthRecord(hr);
    this.hideHealthRecordAttachmentModal();
    this.renderHealthRecord();
    this.showToast('Prilog obrisan ✅');
  };

  App.prototype._hrComputeSpecialistViews = function(snapshot) {
    const tags = arrify(snapshot?.key_findings || []);
    const next = arrify(snapshot?.next_steps || []);
    const red = arrify(snapshot?.red_flags || []);
    const all = (tags.join(' ') + ' ' + next.join(' ') + ' ' + red.join(' ')).toLowerCase();

    function pick(keys) {
      const out = [];
      keys.forEach(k => { if (all.includes(k.toLowerCase())) out.push(k); });
      return out;
    }

    const views = [
      { id:'internista', title:'Internista', focus: pick(['glukoza','insulin','homa','lipid','trigliceridi','hdl','ldl','krvni pritisak']), questions:[
        'Da li postoji potreba za dodatnim testovima (HbA1c, OGTT, apoB)?',
        'Da li su potrebne kontrole u 3 meseca ili ranije?'
      ]},
      { id:'endokrinolog', title:'Endokrinolog / metabolizam', focus: pick(['homa','insulin','tsh','ft4','vitamin d']), questions:[
        'Da li je potrebno ciljano ispitivanje štitaste žlezde ili metabolizma?',
        'Koji je plan praćenja (kontrola, terapija, ishrana)?'
      ]},
      { id:'nefrolog', title:'Nefrolog / bubrezi', focus: pick(['egfr','kreatinin','cistatin','urin','albumin']), questions:[
        'Da li eGFR trend zahteva dodatnu obradu (ACR, urin sediment)?',
        'Koji je optimalan interval kontrole kreatinina/eGFR?'
      ]},
      { id:'gastro', title:'Gastro / hepatologija', focus: pick(['alt','ast','jetra','gama','bilirubin']), questions:[
        'Da li su potrebne dodatne analize jetre ili UZ abdomena?',
        'Da li postoji sumnja na masnu jetru i koji je plan kontrole?'
      ]},
      { id:'kardiolog', title:'Kardiolog / vaskularni rizik', focus: pick(['ldl','hdl','trigliceridi','chol','hs-crp']), questions:[
        'Procena kardiovaskularnog rizika i ciljevi za lipide.',
        'Da li je potreban EKG/UZ srca ili terapijske korekcije?'
      ]},
      { id:'hematologija', title:'Hematologija / KKS', focus: pick(['kks','hemoglobin','leukociti','trombociti','crp']), questions:[
        'Da li KKS/upalni parametri zahtevaju ponavljanje ili dodatnu dijagnostiku?',
        'Koji je interval praćenja?'
      ]}
    ];

    return views.map(v => Object.assign({}, v, { relevant: v.focus.length || red.length, red_flags: red.slice(0,5), next_steps: next.slice(0,5) }));
  };

  App.prototype.runHealthRecordCompare = function() {
    const hr = this._getHealthRecord();
    const snaps = hr.lab_snapshots || [];
    const ida = document.getElementById('hr-compare-a')?.value || '';
    const idb = document.getElementById('hr-compare-b')?.value || '';
    const idc = document.getElementById('hr-compare-c')?.value || '';
    const a = snaps.find(s => String(s.id) === String(ida)) || null;
    const b = snaps.find(s => String(s.id) === String(idb)) || null;
    const c = snaps.find(s => String(s.id) === String(idc)) || null;
    if (!a || !b) return alert('Izaberi A i B snapshot.');

    function setOfTags(s){ return new Set(arrify(s?.key_findings || []).map(x => String(x))); }
    const sa = setOfTags(a), sb = setOfTags(b), sc = c ? setOfTags(c) : null;

    function diff(s1, s2){
      const added=[], removed=[], same=[];
      s2.forEach(v => { if (!s1.has(v)) added.push(v); else same.push(v); });
      s1.forEach(v => { if (!s2.has(v)) removed.push(v); });
      return { added, removed, same };
    }
    const ab = diff(sa, sb);
    const ac = sc ? diff(sa, sc) : null;

    const out = document.getElementById('hr-compare-out');
    if (out) {
      const card = (title, list) => `<div class="hr-list-card"><div style="font-weight:900;color:#1f3f5b;">${this.escapeHtml(title)}</div><div style="margin-top:8px;">${list.length? list.map(v=>`<span class="hr-tag">${this.escapeHtml(v)}</span>`).join('') : '<span class="lab-inline-note">nema</span>'}</div></div>`;
      out.innerHTML = `
        <div class="hr-grid two">
          ${card('Novo u B (u odnosu na A)', ab.added)}
          ${card('Nestalo iz B (u odnosu na A)', ab.removed)}
        </div>
        ${c ? `<div class="hr-grid two" style="margin-top:12px;">
          ${card('Novo u C (u odnosu na A)', (ac?.added||[]))}
          ${card('Nestalo iz C (u odnosu na A)', (ac?.removed||[]))}
        </div>` : ''}
      `;
    }

    const ref = c && c.report_date && b.report_date && c.report_date > b.report_date ? c : b;
    hr.specialist_views = {
      based_on_snapshot_id: ref.id,
      generated_at: new Date().toISOString(),
      views: this._hrComputeSpecialistViews(ref)
    };
    this._saveHealthRecord(hr);
    this.renderHealthRecord();
  };

  App.prototype.clearHealthRecordCompare = function() {
    const out = document.getElementById('hr-compare-out');
    if (out) out.innerHTML = '';
    ['hr-compare-a','hr-compare-b','hr-compare-c'].forEach(id => { const el=document.getElementById(id); if (el) el.value=''; });
  };

