  function safeParse(raw, fallback) {
    try { return JSON.parse(raw); } catch(_) { return fallback; }
  }
  function arrify(v) {
    if (Array.isArray(v)) return v.filter(Boolean);
    if (v === null || v === undefined || v === '') return [];
    return [v];
  }
  function slugify(s) {
    return String(s || 'item')
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .toLowerCase().replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '').slice(0, 64) || 'item';
  }
  function uid(prefix) {
    return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  }
  function uniqueBy(list, keyFn) {
    const out = [];
    const seen = new Set();
    arrify(list).forEach((it) => {
      const key = String(keyFn(it) || '');
      if (key && seen.has(key)) return;
      if (key) seen.add(key);
      out.push(it);
    });
    return out;
  }
  function stripHtml(raw) {
    return String(raw || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  }
  function normalizeText(raw) {
    return String(raw || '').replace(/\s+/g, ' ').trim();
  }
  function normalizeLabel(raw) {
    const base = normalizeText(raw)
      .replace(/\b\(([^)]*)\)\s*$/,'')
      .replace(/\s*[-–—]\s*(high|low|normal|borderline|povišeno|sniženo|granično)$/i,'')
      .trim();
    return base || normalizeText(raw);
  }
  function parseNumericValue(raw) {
    if (raw === null || raw === undefined || raw === '') return null;
    if (typeof raw === 'number' && Number.isFinite(raw)) return raw;
    let s = String(raw).trim();
    if (!s) return null;
    if (/^\d{4}-\d{2}-\d{2}/.test(s)) return null;
    s = s.replace(/\u00a0/g, ' ');
    const match = s.match(/-?\d+(?:[.,]\d+)?/);
    if (!match) return null;
    const num = Number(match[0].replace(',', '.'));
    return Number.isFinite(num) ? num : null;
  }
  function fmtNum(n) {
    if (!Number.isFinite(n)) return '—';
    const abs = Math.abs(n);
    if (abs >= 100 || Number.isInteger(n)) return String(Math.round(n));
    if (abs >= 10) return n.toFixed(1).replace(/\.0$/, '');
    return n.toFixed(2).replace(/0+$/,'').replace(/\.$/,'');
  }
  function spark(values) {
    const vals = values.filter(v => Number.isFinite(v));
    if (!vals.length) return '';
    const chars = '▁▂▃▄▅▆▇█';
    const min = Math.min(...vals);
    const max = Math.max(...vals);
    if (min === max) return vals.map(() => '▅').join('');
    return vals.map(v => {
      const idx = Math.max(0, Math.min(chars.length - 1, Math.round(((v - min) / (max - min)) * (chars.length - 1))));
      return chars[idx];
    }).join('');
  }
  function trendDirection(first, last) {
    if (!Number.isFinite(first) || !Number.isFinite(last)) return '—';
    const delta = last - first;
    if (Math.abs(delta) < 1e-9) return '→ stabilno';
    return delta > 0 ? '↗ porast' : '↘ pad';
  }


