  App.prototype._labExtractNumericItems = function(report) {
    const items = [];
    const seen = new Set();
    const add = (labelRaw, valueRaw, unitRaw, meta={}) => {
      const label = normalizeLabel(labelRaw);
      const numeric = parseNumericValue(valueRaw);
      if (!label || !Number.isFinite(numeric)) return;
      const unit = normalizeText(unitRaw || '');
      const key = slugify(label) + '|' + unit.toLowerCase();
      if (seen.has(key)) return;
      seen.add(key);
      items.push({
        key,
        label,
        numeric_value: numeric,
        value_raw: normalizeText(valueRaw),
        unit,
        status: normalizeText(meta.status || ''),
        importance: normalizeText(meta.importance || ''),
        source: meta.source || 'raw'
      });
    };

    arrify(report?.key_findings).forEach((it) => {
      if (!it || typeof it !== 'object') return;
      add(it.param || it.name || it.test, it.numeric_value ?? it.value ?? it.result, it.unit || it.units, {
        status: it.status,
        importance: it.importance,
        source: 'key_findings'
      });
    });

    const visit = (node, depth=0) => {
      if (depth > 8 || node === null || node === undefined) return;
      if (Array.isArray(node)) { node.forEach((x) => visit(x, depth + 1)); return; }
      if (typeof node !== 'object') return;
      const label = node.param || node.name || node.test || node.title || node.label || node.analyte || node.marker;
      const value = node.numeric_value ?? node.result_value ?? node.result ?? node.value ?? node.current;
      const unit = node.unit || node.units || node.measure_unit || node.reference_unit;
      if (label !== undefined && value !== undefined) {
        add(label, value, unit, { status: node.status || node.flag || node.interpretation, source: 'raw' });
      }
      Object.keys(node).forEach((k) => {
        if (/^(param|name|test|title|label|analyte|marker|numeric_value|result_value|result|value|current|unit|units|measure_unit|reference_unit|status|flag|interpretation)$/i.test(k)) return;
        visit(node[k], depth + 1);
      });
    };
    visit(report?.raw || report);

    const index = {};
    items.forEach((it) => { index[it.key] = { label: it.label, numeric_value: it.numeric_value, unit: it.unit, status: it.status, importance: it.importance, source: it.source }; });
    return { items, index };
  };

  const origBuildLabSnapshot37 = App.prototype._buildLabSnapshotFromReport;
  App.prototype._buildLabSnapshotFromReport = function(report) {
    const base = origBuildLabSnapshot37.apply(this, arguments);
    const numeric = this._labExtractNumericItems(report || {});
    base.key_findings_struct = arrify(report?.key_findings).map((it) => {
      if (!it || typeof it !== 'object') return { value: String(it) };
      return {
        param: normalizeText(it.param || it.name || ''),
        value: normalizeText(it.value || it.result || ''),
        numeric_value: Number.isFinite(parseNumericValue(it.numeric_value ?? it.value ?? it.result)) ? parseNumericValue(it.numeric_value ?? it.value ?? it.result) : null,
        unit: normalizeText(it.unit || it.units || ''),
        status: normalizeText(it.status || ''),
        importance: normalizeText(it.importance || '')
      };
    });
    base.report_id = normalizeText(report?.metadata?.report_id || '');
    base.qa_status = normalizeText(report?.qa?.status || report?.metadata?.qa_status || '');
    base.snapshot_schema_version = '2';
    base.numeric_version = '1';
    base.numeric = numeric;
    return base;
  };

  App.prototype._hrGetTrendDataset = function(hr) {
    const snaps = arrify(hr?.lab_snapshots).slice().sort((a, b) => String(a.report_date || a.created_at || '').localeCompare(String(b.report_date || b.created_at || '')));
    const labelMap = new Map();
    const seriesMap = new Map();
    snaps.forEach((snap) => {
      const numeric = snap.numeric && snap.numeric.items ? snap.numeric : { items: [] };
      arrify(numeric.items).forEach((item) => {
        const key = String(item.key || slugify(item.label) + '|' + String(item.unit || '').toLowerCase());
        labelMap.set(key, { key, label: item.label || key, unit: item.unit || '' });
        if (!seriesMap.has(key)) seriesMap.set(key, []);
        seriesMap.get(key).push({
          snapshot_id: snap.id,
          report_date: snap.report_date || '',
          created_at: snap.created_at || '',
          title: snap.title || snap.patient_name || 'Lab Snapshot',
          value: Number(item.numeric_value),
          unit: item.unit || '',
          status: item.status || ''
        });
      });
    });
    const params = Array.from(labelMap.values()).sort((a, b) => a.label.localeCompare(b.label, 'sr'));
    return { params, seriesMap, snaps };
  };

  App.prototype._renderHealthRecordTrend = function(hr) {
    const host = document.getElementById('hr-trend-out');
    const sel = document.getElementById('hr-trend-param');
    const kpi = document.getElementById('hr-trend-kpi');
    if (!host || !sel || !kpi) return;
    const ds = this._hrGetTrendDataset(hr || this._getHealthRecord());
    const current = localStorage.getItem(HR_TREND_PARAM_KEY) || sel.value || '';
    sel.innerHTML = ds.params.length ? ds.params.map((p) => `<option value="${this.escapeHtml(p.key)}">${this.escapeHtml(p.label)}${p.unit ? ' (' + this.escapeHtml(p.unit) + ')' : ''}</option>`).join('') : '<option value="">— nema numerike —</option>';
    if (current && Array.from(sel.options).some(o => o.value === current)) sel.value = current;
    if (!sel.value && sel.options.length) sel.value = sel.options[0].value;
    sel.onchange = () => { try { localStorage.setItem(HR_TREND_PARAM_KEY, sel.value || ''); } catch(_) {} this.refreshHealthRecordTrend(); };
    const paramKey = sel.value || '';
    const series = paramKey ? (ds.seriesMap.get(paramKey) || []) : [];
    kpi.textContent = String(series.length || 0);
    if (!series.length) {
      host.innerHTML = '<div class="lab-empty">Još nema dovoljno numeričkih snapshot-a za trend. Sačuvaj nove LAB snapshot-e iz ove verzije naviše.</div>';
      return;
    }
    const values = series.map(x => Number(x.value)).filter(Number.isFinite);
    const first = values[0];
    const last = values[values.length - 1];
    const delta = Number.isFinite(first) && Number.isFinite(last) ? last - first : null;
    const pct = Number.isFinite(first) && first !== 0 && Number.isFinite(last) ? ((last - first) / first) * 100 : null;
    const param = ds.params.find(p => p.key === paramKey) || { label: paramKey, unit: '' };
    const enough = series.length >= 6;
    host.innerHTML = `
      <div class="hr-kpi-row">
        <div class="lab-kpi-card"><b>Parametar</b>${this.escapeHtml(param.label)}${param.unit ? ' (' + this.escapeHtml(param.unit) + ')' : ''}</div>
        <div class="lab-kpi-card"><b>Trend</b>${this.escapeHtml(trendDirection(first, last))}</div>
        <div class="lab-kpi-card"><b>Promena</b>${delta === null ? '—' : this.escapeHtml((delta > 0 ? '+' : '') + fmtNum(delta) + (param.unit ? ' ' + param.unit : ''))}</div>
        <div class="lab-kpi-card"><b>% promena</b>${pct === null ? '—' : this.escapeHtml((pct > 0 ? '+' : '') + fmtNum(pct) + '%')}</div>
        <div class="lab-kpi-card"><b>6+ snapshot-a</b>${enough ? 'da ✅' : 'ne još'}</div>
      </div>
      <div class="hr-list-card">
        <div style="font-weight:900;color:#1f3f5b;">Sparkline</div>
        <div class="hr-spark" style="margin-top:8px;">${this.escapeHtml(spark(values) || '—')}</div>
        <div class="hr-sub" style="margin-top:6px;">Prvi: <b>${this.escapeHtml(fmtNum(first))}</b>${param.unit ? ' ' + this.escapeHtml(param.unit) : ''} • Poslednji: <b>${this.escapeHtml(fmtNum(last))}</b>${param.unit ? ' ' + this.escapeHtml(param.unit) : ''}</div>
      </div>
      <table class="hr-trend-table">
        <thead><tr><th>Datum</th><th>Snapshot</th><th>Vrednost</th><th>Status</th></tr></thead>
        <tbody>
          ${series.slice().reverse().map(row => `<tr>
            <td>${this.escapeHtml(row.report_date || (row.created_at || '').slice(0,10) || '-')}</td>
            <td>${this.escapeHtml(row.title || row.snapshot_id || 'Lab Snapshot')}</td>
            <td><b>${this.escapeHtml(fmtNum(Number(row.value)))}</b>${row.unit ? ' ' + this.escapeHtml(row.unit) : ''}</td>
            <td>${this.escapeHtml(row.status || '—')}</td>
          </tr>`).join('')}
        </tbody>
      </table>`;
    this._hrLastTrendPayload = {
      generated_at: new Date().toISOString(),
      param,
      summary: { first, last, delta, pct, direction: trendDirection(first, last), spark: spark(values), count: series.length },
      series
    };
  };

  App.prototype.refreshHealthRecordTrend = function() {
    this._renderHealthRecordTrend(this._getHealthRecord());
  };

  App.prototype.copyHealthRecordTrendJson = function() {
    const payload = this._hrLastTrendPayload || null;
    if (!payload) return alert('Prvo osveži trend.');
    navigator.clipboard.writeText(JSON.stringify(payload, null, 2)).then(() => this.showToast('Trend JSON kopiran ✅')).catch(() => alert('Clipboard nije dostupan.'));
  };

  const origRenderHealthRecord37 = App.prototype.renderHealthRecord;
  App.prototype.renderHealthRecord = function() {
    origRenderHealthRecord37.apply(this, arguments);
    const hr = this._getHealthRecord();
    try { this._ensureHealthRecordEnhancements37(); } catch(_) {}
    try { this._renderHealthRecordCompareAndAttachments(hr); } catch(_) {}
    try { this._renderHealthRecordSpecialistViews(hr); } catch(_) {}
    try { this._renderHealthRecordTrend(hr); } catch(_) {}
    try { this._renderSpecialistAiWorkflow(hr); } catch(_) {}
  };

  const origComputeSpecialistViews37 = App.prototype._hrComputeSpecialistViews;
  App.prototype._hrComputeSpecialistViews = function(snapshot) {
    const base = origComputeSpecialistViews37.apply(this, arguments) || [];
    const keyText = [
      ...arrify(snapshot?.key_findings),
      ...arrify(snapshot?.next_steps),
      ...arrify(snapshot?.red_flags),
      ...arrify(snapshot?.quick_summary),
      ...arrify(snapshot?.numeric?.items).map(it => `${it.label} ${it.status || ''}`)
    ].join(' ').toLowerCase();
    const pick = (keys) => uniqueBy(keys.filter(k => keyText.includes(String(k).toLowerCase())).map(k => normalizeLabel(k)), x => x.toLowerCase());
    const extra = [
      { id:'ginekolog', title:'Ginekolog', focus: pick(['ginekolog','menstru','pcos','estradiol','progesteron','fsh','lh','prolaktin']), questions:['Da li hormonski profil ili ciklus zahtevaju dodatnu obradu?','Da li postoji potreba za UZ i dodatnim ginekološkim kontrolama?'] },
      { id:'radiolog', title:'Radiolog / snimanja', focus: pick(['uz abdomena','ultrazvuk','rtg','ct','mri','radiolog','snimanje']), questions:['Koji imaging pregled je najracionalniji sledeći korak?','Da li postoje jasne indikacije i prioritet snimanja?'] },
      { id:'oftalmolog', title:'Oftalmolog', focus: pick(['vid','retina','oftalmolog','oči','glaukom']), questions:['Da li simptomi ili rizici zahtevaju oftalmološki pregled?','Da li su potrebni dodatni testovi vida / očnog pritiska?'] },
      { id:'dentista', title:'Dentista / stomatolog', focus: pick(['zubi','dent','stomat','parodont','vilica']), questions:['Da li postoje znaci oralnog fokusa ili upale koje treba proveriti?','Da li je potreban stomatološki pregled / ortopan?'] },
      { id:'imunolog', title:'Imunolog', focus: pick(['autoimuno','crp','imun','alerg','igg','iga','igm']), questions:['Da li obrazac nalaza i simptoma traži imunološku obradu?','Koje dodatne imunološke analize imaju najviše smisla?'] }
    ].map(v => Object.assign({}, v, { relevant: v.focus.length || arrify(snapshot?.red_flags).length, red_flags: arrify(snapshot?.red_flags).slice(0,5), next_steps: arrify(snapshot?.next_steps).slice(0,5) }));
    return uniqueBy([...base, ...extra], x => x.id);
  };

  App.prototype._renderHealthRecordSpecialistViews = function(hr) {
    const host = document.getElementById('hr-specialist-views');
    if (!host) return;
    const sv = hr.specialist_views || {};
    const views = arrify(sv.views);
    if (!views.length) {
      host.innerHTML = '<div class="lab-empty">Nema specialist view-a još. Pokreni Compare da se generiše na osnovu izabranog snapshot-a.</div>';
      return;
    }
    let selected = localStorage.getItem(HR_SELECTED_SPECIALIST_KEY) || views[0].id;
    if (!views.some(v => v.id === selected)) selected = views[0].id;
    const isMobile = window.matchMedia && window.matchMedia('(max-width: 759px)').matches;
    const selectHtml = `<select id="hr-specialist-mobile-select" class="lab-select">${views.map(v => `<option value="${this.escapeHtml(v.id)}">${this.escapeHtml(v.title || v.id)}</option>`).join('')}</select>`;
    const chipsHtml = views.map(v => `<button type="button" class="hr-chip ${v.id === selected ? 'active' : ''}" onclick="app.selectHealthRecordSpecialist('${this.escapeHtml(v.id)}')">${this.escapeHtml(v.title || v.id)}</button>`).join('');
    const renderCard = (v) => `
      <div class="hr-list-card">
        <div style="font-weight:900;color:#1f3f5b;">${this.escapeHtml(v.title || v.id)}</div>
        ${arrify(v.focus).length ? `<div style="margin-top:10px;">${arrify(v.focus).map(x => `<span class="hr-tag">${this.escapeHtml(String(x))}</span>`).join('')}</div>` : '<div class="hr-sub">Nema eksplicitno prepoznatih tagova za ovaj prikaz.</div>'}
        ${arrify(v.red_flags).length ? `<div style="margin-top:10px;"><b>Red flags</b>${arrify(v.red_flags).map(x=>`<div class="hr-mini">• ${this.escapeHtml(String(x))}</div>`).join('')}</div>` : ''}
        ${arrify(v.next_steps).length ? `<div style="margin-top:10px;"><b>Sledeći koraci</b>${arrify(v.next_steps).map(x=>`<div class="hr-mini">• ${this.escapeHtml(String(x))}</div>`).join('')}</div>` : ''}
        ${arrify(v.questions).length ? `<div style="margin-top:10px;"><b>Pitanja za lekara</b>${arrify(v.questions).map(x=>`<div class="hr-mini">• ${this.escapeHtml(String(x))}</div>`).join('')}</div>` : ''}
      </div>`;
    const shown = isMobile ? views.filter(v => v.id === selected) : views;
    host.innerHTML = `
      <div class="lab-inline-note">based_on_snapshot_id: <b>${this.escapeHtml(String(sv.based_on_snapshot_id || ''))}</b> • generated_at: ${this.escapeHtml(String(sv.generated_at || ''))}</div>
      <div class="hr-specialist-toolbar">
        <div style="min-width:${isMobile ? '100%' : '220px'}; flex:${isMobile ? '1 1 100%' : '0 0 260px'};">${selectHtml}</div>
        <div class="hr-chip-row">${chipsHtml}</div>
      </div>
      <div class="hr-specialist-grid ${isMobile ? 'mobile-single' : 'desktop-grid'}">${shown.map(renderCard).join('')}</div>`;
    const sel = document.getElementById('hr-specialist-mobile-select');
    if (sel) {
      sel.value = selected;
      sel.onchange = () => this.selectHealthRecordSpecialist(sel.value || '');
    }
    const aiSel = document.getElementById('hr-ai-specialist');
    if (aiSel) {
      aiSel.innerHTML = views.map(v => `<option value="${this.escapeHtml(v.id)}">${this.escapeHtml(v.title || v.id)}</option>`).join('');
      aiSel.value = selected;
    }
  };

  App.prototype.selectHealthRecordSpecialist = function(id) {
    try { localStorage.setItem(HR_SELECTED_SPECIALIST_KEY, String(id || '')); } catch(_) {}
    const aiSel = document.getElementById('hr-ai-specialist');
    if (aiSel && id) aiSel.value = id;
    this._renderHealthRecordSpecialistViews(this._getHealthRecord());
  };

  App.prototype._renderHealthRecordCompareAndAttachments = function(hr) {
    const snaps = arrify(hr.lab_snapshots).slice(0, 50);
    const optHtml = (s) => `<option value="${this.escapeHtml(String(s.id||''))}">${this.escapeHtml((s.report_date||'') + ' — ' + (s.title||s.patient_name||'Lab Snapshot'))}</option>`;
    ['hr-compare-a','hr-compare-b','hr-compare-c'].forEach((id) => {
      const sel = document.getElementById(id);
      if (!sel) return;
      const cur = sel.value || '';
      sel.innerHTML = `<option value="">— izaberi —</option>` + snaps.map(optHtml).join('');
      if (cur) sel.value = cur;
    });
    const tType = document.getElementById('hr-attach-target-type');
    const tSel = document.getElementById('hr-attach-target-id');
    if (tType && tSel) {
      const cur = tSel.value || '';
      const mode = String(tType.value || 'event');
      const list = mode === 'therapy' ? arrify(hr.therapy_records) : arrify(hr.medical_events);
      tSel.innerHTML = `<option value="">— izaberi —</option>` + list.map(it => {
        const label = [it.date, (mode === 'therapy' ? (it.name || 'Terapija') : (it.title || 'Događaj'))].filter(Boolean).join(' • ');
        return `<option value="${this.escapeHtml(String(it.id||''))}">${this.escapeHtml(label)}</option>`;
      }).join('');
      if (cur) tSel.value = cur;
      if (!tSel.value && list[0]?.id) tSel.value = String(list[0].id);
      tType.onchange = () => { try { this._renderHealthRecordCompareAndAttachments(this._getHealthRecord()); } catch(_) {} };
    }
    const host = document.getElementById('hr-attachments-list');
    if (!host) return;
    const filter = localStorage.getItem(HR_ATTACHMENT_FILTER_KEY) || 'all';
    const atts = arrify(hr.attachments);
    const relatedMap = {};
    arrify(hr.medical_events).forEach(ev => arrify(ev.attachment_ids).forEach(id => { relatedMap[String(id)] = { type:'event', title: ev.title || 'Događaj', date: ev.date || '' }; }));
    arrify(hr.therapy_records).forEach(th => arrify(th.attachment_ids).forEach(id => { if (!relatedMap[String(id)]) relatedMap[String(id)] = { type:'therapy', title: th.name || 'Terapija', date: th.date || '' }; }));
    const filtered = atts.filter((a) => {
      if (filter === 'all') return true;
      const rel = relatedMap[String(a.id)] || null;
      return rel && rel.type === filter;
    });
    const btn = (id, label) => `<button type="button" class="hr-filter-btn ${filter === id ? 'active' : ''}" onclick="app.setHealthRecordAttachmentFilter('${id}')">${label}</button>`;
    host.innerHTML = `
      <div class="hr-filter-row">
        ${btn('all','Sve')}
        ${btn('event','Događaji')}
        ${btn('therapy','Terapije')}
      </div>
      <div class="lab-inline-note">Prikaz: <b>${this.escapeHtml(String(filtered.length))}</b> / ${this.escapeHtml(String(atts.length))} priloga</div>
      <div class="hr-thumb-grid">
        ${filtered.length ? filtered.map((att) => {
          const rel = relatedMap[String(att.id)] || null;
          const kind = String(att.kind || 'bin');
          const thumb = (kind === 'image' && att.inline && att.data_url)
            ? `<img src="${att.data_url}" alt="thumb" />`
            : `<div class="hr-attach-thumb-fallback">${kind === 'pdf' ? '📄' : kind === 'html' ? '🌐' : kind === 'text' ? '📝' : '📦'}</div>`;
          return `<div class="hr-attach-card">
            <div class="hr-attach-thumb-wrap" onclick="app.showHealthRecordAttachment('${this.escapeHtml(String(att.id))}')">${thumb}</div>
            <div style="font-weight:900;color:#1f3f5b;margin-top:10px;">${this.escapeHtml(att.name || 'prilog')}</div>
            <div class="hr-sub">${this.escapeHtml([att.kind, (att.size||0)+' B'].join(' • '))}</div>
            ${rel ? `<div class="hr-mini" style="margin-top:8px;"><b>${rel.type === 'event' ? 'Događaj' : 'Terapija'}:</b> ${this.escapeHtml([rel.date, rel.title].filter(Boolean).join(' • '))}</div>` : '<div class="hr-mini" style="margin-top:8px;">Nije vezan za cilj.</div>'}
            <div class="hr-history-actions"><button type="button" onclick="app.showHealthRecordAttachment('${this.escapeHtml(String(att.id))}')">👁 Otvori</button></div>
          </div>`;
        }).join('') : '<div class="lab-empty">Još nema priloga za ovaj filter.</div>'}
      </div>`;
  };

  App.prototype.setHealthRecordAttachmentFilter = function(mode) {
    try { localStorage.setItem(HR_ATTACHMENT_FILTER_KEY, String(mode || 'all')); } catch(_) {}
    this._renderHealthRecordCompareAndAttachments(this._getHealthRecord());
  };

  App.prototype.showHealthRecordAttachment = function(attId) {
    this._hrEnsureAttachmentIndex && this._hrEnsureAttachmentIndex();
    const hr = this._getHealthRecord();
    const att = this._hrGetAttachmentById(hr, attId);
    if (!att) return alert('Prilog nije pronađen.');
    this._hrCurrentAttachmentId = att.id;
    const modal = document.getElementById('hr-attach-modal');
    const title = document.getElementById('hr-attach-modal-title');
    const prev = document.getElementById('hr-attach-modal-preview');
    const meta = document.getElementById('hr-attach-modal-meta');
    if (!modal || !title || !prev || !meta) return;
    modal.classList.add('hr-drawer-backdrop','open');
    const panel = modal.querySelector('.hr-modal');
    if (panel) panel.classList.add('hr-drawer-panel');
    title.textContent = `📎 ${att.name || 'Prilog'}`;
    prev.innerHTML = '';
    const kind = String(att.kind || 'bin');
    if (att.inline && att.data_url) {
      if (kind === 'image') prev.innerHTML = `<img src="${att.data_url}" alt="preview" style="width:100%;height:auto;display:block;" />`;
      else if (kind === 'pdf') prev.innerHTML = `<iframe src="${att.data_url}"></iframe>`;
      else if (kind === 'html') prev.innerHTML = `<iframe sandbox="allow-same-origin" src="${att.data_url}"></iframe>`;
      else if (kind === 'text') prev.innerHTML = `<pre style="margin:0;padding:12px;white-space:pre-wrap;line-height:1.5;">${this.escapeHtml(att.text_excerpt || '[tekst]')}</pre>`;
      else prev.innerHTML = '<div style="padding:12px;">Inline fajl je sačuvan, ali nema preview za ovaj tip.</div>';
    } else {
      prev.innerHTML = '<div style="padding:12px;">Ovaj prilog je sačuvan kao <b>metadata-only</b> (prevelik ili nepodržan za inline). Preuzimanje nije dostupno bez ponovnog uploada.</div>';
    }
    let relation = 'Nije vezan.';
    arrify(hr.medical_events).forEach(ev => { if (arrify(ev.attachment_ids).includes(att.id)) relation = `Događaj • ${[ev.date, ev.title].filter(Boolean).join(' • ')}`; });
    arrify(hr.therapy_records).forEach(th => { if (arrify(th.attachment_ids).includes(att.id)) relation = `Terapija • ${[th.date, th.name].filter(Boolean).join(' • ')}`; });
    meta.innerHTML = `
      <div class="lab-kpi-card"><b>Tip</b>${this.escapeHtml(kind)}</div>
      <div class="lab-kpi-card"><b>MIME</b>${this.escapeHtml(att.mime || '-')}</div>
      <div class="lab-kpi-card"><b>Veličina</b>${this.escapeHtml(String(att.size || 0))} B</div>
      <div class="lab-kpi-card"><b>Datum</b>${this.escapeHtml((att.created_at || '').slice(0,16).replace('T',' ') || '-')}</div>
      <div class="lab-kpi-card"><b>Veza</b>${this.escapeHtml(relation)}</div>
      <div class="lab-kpi-card"><b>Fallback</b>${att.inline ? 'inline preview' : 'metadata-only'}</div>`;
    modal.style.display = 'block';
  };

  const origHideAtt37 = App.prototype.hideHealthRecordAttachmentModal;
  App.prototype.hideHealthRecordAttachmentModal = function() {
    const modal = document.getElementById('hr-attach-modal');
    if (modal) {
      modal.style.display = 'none';
      modal.classList.remove('open');
    }
    origHideAtt37 && origHideAtt37.apply(this, arguments);
  };

  App.prototype._getActiveAnamnezaForHealthRecord = function() {
    try {
      if (window.SINET_ProfilesCore && window.SINET_ProfilesCore.getActiveProfile) {
        const p = window.SINET_ProfilesCore.getActiveProfile();
        if (p) return p;
      }
    } catch(_) {}
    return safeParse(localStorage.getItem('ANAMNEZA_LAST_PATIENT') || 'null', null);
  };

  App.prototype.importActiveAnamnezaIntoHealthRecord = function() {
    const active = this._getActiveAnamnezaForHealthRecord();
    if (!active) return alert('Nema aktivne Anamneze / profila.');
    const hr = this._getHealthRecord();
    hr.profile.display_name = active.displayName || active.ime_prezime || active.ime || hr.profile.display_name || 'Korisnik';
    hr.profile.age = active.age || active.starost || hr.profile.age || '';
    hr.profile.sex = active.sex || active.pol || hr.profile.sex || '';
    hr.profile.notes = [active.primaryDiagnosis, active.noteSummary, active.diagnoza, active.licna_anamneza].filter(Boolean).join(' • ').slice(0, 1000);
    hr.analytics = hr.analytics || {};
    hr.analytics.active_anamneza = active;
    this._saveHealthRecord(hr);
    this.renderHealthRecord();
    this.showToast('Aktivna Anamneza uvezena ✅');
  };

  App.prototype._topNumericLinesForSpecialist = function(hr, specialistView) {
    const ds = this._hrGetTrendDataset(hr);
    const focusText = arrify(specialistView?.focus).join(' ').toLowerCase();
    const candidates = ds.params.filter(p => !focusText || focusText.includes((p.label || '').toLowerCase()) || (specialistView?.title || '').toLowerCase().includes((p.label || '').toLowerCase().slice(0, 5)));
    const picked = (candidates.length ? candidates : ds.params).slice(0, 5);
    return picked.map((p) => {
      const series = ds.seriesMap.get(p.key) || [];
      if (!series.length) return null;
      const first = Number(series[0].value);
      const last = Number(series[series.length - 1].value);
      return `${p.label}${p.unit ? ` (${p.unit})` : ''}: ${fmtNum(first)} → ${fmtNum(last)} (${trendDirection(first, last)})`;
    }).filter(Boolean);
  };

  App.prototype._buildSpecialistAiPromptPack = function(hr, specialistId) {
    const sv = hr.specialist_views || {};
    const views = arrify(sv.views);
    const selected = views.find(v => String(v.id) === String(specialistId)) || views[0] || null;
    const anam = hr.analytics?.active_anamneza || this._getActiveAnamnezaForHealthRecord() || null;
    const questions = uniqueBy([
      ...arrify(selected?.questions),
      ...arrify(selected?.next_steps).map(x => `Da li ${String(x).replace(/[.。]+$/,'').toLowerCase()}?`),
      ...arrify(selected?.red_flags).map(x => `Kako tumačiti red flag: ${x}?`)
    ], x => String(x).toLowerCase()).slice(0, 12);
    const numericLines = this._topNumericLinesForSpecialist(hr, selected);
    const prompt = [
      `SINET Specialist AI Workflow — ${selected?.title || 'Specijalista'}`,
      '',
      'Uloga: medicinsko-informativni asistent. Ne postavljaj konačnu dijagnozu samo iz ovih podataka.',
      '',
      '1) Pacijent / profil',
      `- Ime/oznaka: ${hr.profile?.display_name || 'Korisnik'}`,
      `- Godine: ${hr.profile?.age || ''}`,
      `- Pol: ${hr.profile?.sex || ''}`,
      anam ? `- Aktivna Anamneza: ${normalizeText(anam.displayName || anam.ime_prezime || anam.ime || 'profil')}` : '- Aktivna Anamneza: nije dostupna',
      anam ? `- Anamneza sažetak: ${normalizeText(anam.noteSummary || anam.diagnoza || anam.licna_anamneza || '')}` : '',
      '',
      '2) Current snapshot',
      ...arrify(hr.current_snapshot?.summary).map(x => `- ${x}`),
      ...arrify(hr.current_snapshot?.priorities).map(x => `- Prioritet: ${x}`),
      hr.current_snapshot?.last_report_date ? `- Poslednji datum nalaza: ${hr.current_snapshot.last_report_date}` : '',
      '',
      `3) Fokus za ${selected?.title || 'specijalistu'}`,
      ...arrify(selected?.focus).map(x => `- Fokus: ${x}`),
      ...arrify(selected?.red_flags).map(x => `- Red flag: ${x}`),
      ...arrify(selected?.next_steps).map(x => `- Sledeći korak: ${x}`),
      '',
      '4) Numerički trendovi',
      ...(numericLines.length ? numericLines.map(x => `- ${x}`) : ['- Nema dovoljno numerike za trend.']),
      '',
      '5) Zadatak za AI',
      '- Napiši sažetak za izabranog specijalistu.',
      '- Odvoji: uredno / granično / odstupanje / prioritet kontrole.',
      '- Izvuci racionalna pitanja za lekara i red flags.',
      '- Ne uvoditi terapiju bez jasne napomene da pregled odlučuje.',
      '',
      '6) Pitanja za lekara',
      ...questions.map(x => `- ${x}`)
    ].filter(Boolean).join('\n');
    return {
      id: uid('specialist-ai'),
      generated_at: new Date().toISOString(),
      specialist_id: selected?.id || '',
      specialist_title: selected?.title || '',
      based_on_snapshot_id: sv.based_on_snapshot_id || '',
      patient: { display_name: hr.profile?.display_name || '', age: hr.profile?.age || '', sex: hr.profile?.sex || '' },
      questions_for_doctor: questions,
      numeric_trends: numericLines,
      prompt_text: prompt
    };
  };

  App.prototype.generateSpecialistAiWorkflow = function() {
    const hr = this._getHealthRecord();
    const sel = document.getElementById('hr-ai-specialist');
    const specialistId = String(sel?.value || localStorage.getItem(HR_SELECTED_SPECIALIST_KEY) || '');
    if (!arrify(hr.specialist_views?.views).length) return alert('Prvo generiši Specialist views kroz Compare.');
    const pack = this._buildSpecialistAiPromptPack(hr, specialistId);
    const ta = document.getElementById('hr-ai-prompt');
    if (ta) ta.value = pack.prompt_text;
    hr.analytics = hr.analytics || {};
    hr.analytics.specialist_ai_history = [pack, ...arrify(hr.analytics.specialist_ai_history)].slice(0, 20);
    this._saveHealthRecord(hr);
    this._hrLastAiPrompt = pack;
    this._renderSpecialistAiWorkflow(this._getHealthRecord());
    this.showToast('Specialist prompt pack spreman ✅');
  };

  App.prototype.copySpecialistAiPrompt = function() {
    const ta = document.getElementById('hr-ai-prompt');
    const txt = String(ta?.value || this._hrLastAiPrompt?.prompt_text || '').trim();
    if (!txt) return alert('Prvo generiši prompt pack.');
    navigator.clipboard.writeText(txt).then(() => this.showToast('Prompt pack kopiran ✅')).catch(() => alert('Clipboard nije dostupan.'));
  };

  App.prototype.exportSpecialistAiPrompt = function() {
    const txt = String(document.getElementById('hr-ai-prompt')?.value || this._hrLastAiPrompt?.prompt_text || '').trim();
    if (!txt) return alert('Prvo generiši prompt pack.');
    const sel = document.getElementById('hr-ai-specialist');
    const sid = String(sel?.value || 'specialist');
    this._downloadText(txt, `SINET_SPECIALIST_PROMPT_${slugify(sid)}_${new Date().toISOString().slice(0,10)}.txt`);
  };

  App.prototype.loadSpecialistAiHistory = function(id) {
    const hr = this._getHealthRecord();
    const item = arrify(hr.analytics?.specialist_ai_history).find(x => String(x.id) === String(id)) || null;
    if (!item) return;
    const ta = document.getElementById('hr-ai-prompt');
    if (ta) ta.value = item.prompt_text || '';
    this._hrLastAiPrompt = item;
    const sel = document.getElementById('hr-ai-specialist');
    if (sel && item.specialist_id) sel.value = item.specialist_id;
  };

  App.prototype.deleteSpecialistAiHistory = function(id) {
    const hr = this._getHealthRecord();
    hr.analytics = hr.analytics || {};
    hr.analytics.specialist_ai_history = arrify(hr.analytics.specialist_ai_history).filter(x => String(x.id) !== String(id));
    this._saveHealthRecord(hr);
    this._renderSpecialistAiWorkflow(this._getHealthRecord());
  };

  App.prototype._renderSpecialistAiWorkflow = function(hr) {
    const anamStatus = document.getElementById('hr-ai-anam-status');
    const aiSel = document.getElementById('hr-ai-specialist');
    const historyHost = document.getElementById('hr-ai-history');
    if (anamStatus) {
      const anam = hr.analytics?.active_anamneza || this._getActiveAnamnezaForHealthRecord();
      anamStatus.textContent = anam ? [anam.displayName || anam.ime_prezime || anam.ime || 'profil', anam.primaryDiagnosis || anam.diagnoza || ''].filter(Boolean).join(' • ') : 'Nije učitana.';
    }
    const views = arrify(hr.specialist_views?.views);
    if (aiSel) {
      const selected = localStorage.getItem(HR_SELECTED_SPECIALIST_KEY) || views[0]?.id || '';
      aiSel.innerHTML = views.length ? views.map(v => `<option value="${this.escapeHtml(v.id)}">${this.escapeHtml(v.title || v.id)}</option>`).join('') : '<option value="">— nema specialist views —</option>';
      if (selected) aiSel.value = selected;
      aiSel.onchange = () => { this.selectHealthRecordSpecialist(aiSel.value || ''); };
    }
    if (historyHost) {
      const hist = arrify(hr.analytics?.specialist_ai_history);
      historyHost.innerHTML = hist.length ? `<div style="margin-top:12px;"><b>Istorija prompt paketa</b>${hist.map(it => `
        <div class="hr-list-card">
          <div style="font-weight:900;color:#1f3f5b;">${this.escapeHtml(it.specialist_title || it.specialist_id || 'Specijalista')}</div>
          <div class="hr-sub">${this.escapeHtml((it.generated_at || '').slice(0,16).replace('T',' '))}</div>
          <div class="hr-history-actions">
            <button type="button" onclick="app.loadSpecialistAiHistory('${this.escapeHtml(String(it.id))}')">↩ Učitaj</button>
            <button type="button" onclick="app.deleteSpecialistAiHistory('${this.escapeHtml(String(it.id))}')">🗑 Obriši</button>
          </div>
        </div>`).join('')}</div>` : '<div class="lab-inline-note" style="margin-top:12px;">Istorija će se pojaviti posle prvog generisanja.</div>';
    }
  };



